{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks server-side encryption",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled. Without encryption, sensitive data stored in the bucket could be exposed if unauthorized access occurs."
    },
    {
      "check_id": "CKV_AWS_52",
      "title": "S3 bucket lacks logging",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have logging enabled. Without logging, it is difficult to track access and detect potential unauthorized access or misconfigurations."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 bucket allows force_destroy",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "LOW",
      "explanation": "The S3 bucket has 'force_destroy' set to true, which allows deletion of the bucket even if it contains objects. This increases the risk of accidental or malicious data loss."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket        = \"smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}\"\n  force_destroy = false\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"AES256\"\n      }\n    }\n  }\n\n  logging {\n    target_bucket = \"log-bucket-name\" # Replace with the name of a logging bucket\n    target_prefix = \"cloudtrail-logs/\"\n  }\n}",
  "fix_summary": "Enabled server-side encryption using AES256 to protect data at rest. Added logging configuration to track access and operations on the bucket. Set 'force_destroy' to false to prevent accidental or malicious data loss."
}
